 Future<void> _addLine(PosAndDrugsProvider pos,InventoryAndPurchaseProvider p)async{final selected=pos.drugs.where((x)=>x.id==drug).toList();final packs=int.tryParse(paidPacks.text)??0;final free=int.tryParse(bonus.text)??0;final cost=double.tryParse(price.text)??-1;final pct=double.tryParse(discount.text)??0;if(selected.isEmpty||warehouse==null||batchNo.text.trim().isEmpty||DateTime.tryParse(expiry.text)==null||packs<=0||free<0||cost<0){_message('أكمل بيانات الدواء والتشغيلة والصلاحية والكميات والسعر');return;}if(selected.first.requiresRefrigeration&&location!=null){final shelf=p.shelves.where((x)=>x.id==location).toList();if(shelf.isNotEmpty&&!shelf.first.isFridge){_message('الدواء المبرد يجب وضعه على رف مبرد');return;}}setState(()=>lines.add(PurchaseLineInput(drugId:drug!,batchNo:batchNo.text.trim(),expiryDate:expiry.text.trim(),warehouseId:warehouse!,qtyPacksPaid:packs,bonusPacks:free,packPrice:cost,locationId:location,lineDiscountPct:pct)));}
